turret, sleeve, main, flare, barrel = piece('turret', 'sleeve', 'main', 'flare', 'barrel')

include "smokeunit.lua"

local rad = math.rad
local COB2RAD = math.pi / 32768
local SIG_AIM = 1
local restore_delay = 0

local function Blow(list, flags)
	for _, p in ipairs(list) do Explode(p, flags) end
end

local function RestoreAfterDelay()
	Sleep(restore_delay)
	Turn(turret, y_axis, 0, rad(49.99))
	Turn(sleeve, x_axis, 0, rad(49.99))
end

local function SetMaxReloadTime(reload)
	restore_delay = reload * 2
end

function script.Create()
	restore_delay = 3000
	StartThread(SmokeUnit, {main})
	SetMaxReloadTime(Spring.UnitScript.GetLongestReloadTime(unitID))
end

function script.SweetSpot()
	return main
end

function script.AimFromWeapon(num)
	return turret
end

function script.QueryWeapon(num)
	return flare
end

function script.AimWeapon(num, heading, pitch)
	Signal(SIG_AIM)
	SetSignalMask(SIG_AIM)
	Turn(turret, y_axis, heading, math.rad(50))  -- TA 3.1c aim speed (was rad(35))
	Turn(sleeve, x_axis, -pitch, math.rad(50))  -- TA 3.1c aim speed (was rad(35))
	WaitForTurn(turret, y_axis)
	WaitForTurn(sleeve, x_axis)
	StartThread(RestoreAfterDelay)
	return true
end

function script.FireWeapon(num)
	Move(barrel, z_axis, -6, 1250)
	Sleep(150)
	WaitForMove(barrel, z_axis)
	Move(barrel, z_axis, 0, 7.5)
end

local function HitByWeapon(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(main, z_axis, -(anglez * COB2RAD), rad(104.99))
	Turn(main, x_axis, anglex * COB2RAD, rad(104.99))
	WaitForTurn(main, z_axis)
	WaitForTurn(main, x_axis)
	Turn(main, z_axis, 0, rad(30))
	Turn(main, x_axis, 0, rad(30))
end

function script.HitByWeapon(x, z)
	StartThread(HitByWeapon, x, z)
end

function script.RockUnit(x, z)
	local anglex, anglez = 500 * z, 500 * x
	Turn(main, x_axis, anglex * COB2RAD, rad(49.99))
	Turn(main, z_axis, -(anglez * COB2RAD), rad(49.99))
	WaitForTurn(main, z_axis)
	WaitForTurn(main, x_axis)
	Turn(main, z_axis, 0, rad(20))
	Turn(main, x_axis, 0, rad(20))
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	if severity <= 25 then
		Explode(barrel, SFX.NONE + SFX.NO_HEATCLOUD)
